public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(
            required=true
            label='Email'
            description='Email address to look up'
        )
        public String email;
    }

    public class Result {
        @InvocableVariable(
            label='Contact Id'
            description='Id of the matching Contact, if found'
        )
        public Id contactId;

        @InvocableVariable(
            label='Found'
            description='True if a matching Contact was found'
        )
        public Boolean found;
    }

    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds an existing Contact by email address. Matching is case-insensitive and ignores leading/trailing spaces. If multiple Contacts match, the earliest created Contact is returned.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> normalizedEmails = new List<String>(requests.size());
        Set<String> emailsNeeded = new Set<String>();

        for (Request request : requests) {
            String normalizedEmail = normalizeEmail(
                request == null ? null : request.email
            );
            normalizedEmails.add(normalizedEmail);

            if (normalizedEmail != null) {
                emailsNeeded.add(normalizedEmail);
            }
        }

        Map<String, Id> contactIdByEmail = new Map<String, Id>();

        if (!emailsNeeded.isEmpty()) {
            // Exactly one SOQL query for the whole batch.
            //
            // SOQL equality/LIKE matching against the Email field cannot be
            // relied upon for case-insensitive matching of bind-variable /
            // lower-cased values (it can fail to return Contacts whose
            // stored Email capitalisation differs from the supplied value),
            // and there is no LOWER() function in SOQL. Wildcard characters
            // in an email would also make LIKE unsafe.
            //
            // Therefore fetch the candidate Contacts in a single query
            // (with sharing, so only records visible to the running user
            // are returned), ordered by earliest CreatedDate, and perform
            // the exact, normalised comparison in Apex. The first Contact
            // seen for a normalised email is therefore the earliest created
            // matching Contact, regardless of stored capitalisation or
            // surrounding spaces, and %/_ in an email are treated literally.
            for (Contact contactRecord : [
                SELECT Id, Email
                FROM Contact
                WHERE Email != null
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String contactEmail = normalizeEmail(contactRecord.Email);

                if (
                    contactEmail != null &&
                    emailsNeeded.contains(contactEmail) &&
                    !contactIdByEmail.containsKey(contactEmail)
                ) {
                    contactIdByEmail.put(contactEmail, contactRecord.Id);
                }
            }
        }

        for (Integer i = 0; i < requests.size(); i++) {
            String normalizedEmail = normalizedEmails[i];
            Id matchedContactId = normalizedEmail == null
                ? null
                : contactIdByEmail.get(normalizedEmail);

            Result result = new Result();
            result.contactId = matchedContactId;
            result.found = matchedContactId != null;
            results.add(result);
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
