@IsTest
private class AddressVerificationServiceTest {

    // ---------------------------------------------------------------------
    // Test setup: persisted data is created in a separate transaction.
    // In this org, @TestSetup DML otherwise leaves callouts with
    // "uncommitted work pending", so EVERY callout-making invocation
    // below is wrapped in Test.startTest()/Test.stopTest() (via the
    // verifyInTestContext / assertThrowsForStatus helpers), which
    // isolates the callout in a fresh execution context.
    // ---------------------------------------------------------------------

    @TestSetup
