    }

    // ---------------------------------------------------------------------
    // Mock
    // ---------------------------------------------------------------------

    private class CapturingMock implements HttpCalloutMock {
        private final Integer statusCode;
        private final String responseBody;

        public Integer callCount = 0;
        public String lastMethod;
        public String lastEndpoint;
        public String lastContentType;
        public String lastBody;

        CapturingMock(Integer statusCode, String responseBody) {
            this.statusCode = statusCode;
            this.responseBody = responseBody;
        }

        public HttpResponse respond(HttpRequest req) {
            callCount++;
            lastMethod = req.getMethod();
            lastEndpoint = req.getEndpoint();
            lastContentType = req.getHeader('Content-Type');
            lastBody = req.getBody();

            HttpResponse res = new HttpResponse();
            res.setStatusCode(statusCode);
            res.setHeader('Content-Type', 'application/json');
            if (responseBody != null) {
                res.setBody(responseBody);
            }
            return res;
        }
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static Account newAccount(
        String street,
        String city,
        String postalCode,
        String country
    ) {
        return new Account(
            Name = 'Acme Test',
            BillingStreet = street,
            BillingCity = city,
            BillingPostalCode = postalCode,
            BillingCountry = country
        );
    }

    private static CapturingMock installMock(Integer statusCode, String responseBody) {
        CapturingMock mock = new CapturingMock(statusCode, responseBody);
        Test.setMock(HttpCalloutMock.class, mock);
        return mock;
    }

