public class AccountScoringJob implements Queueable {
    private static final Integer MAX_ACCOUNTS_PER_EXECUTION = 200;
    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    // 50,000 accounts / 200 per job requires a chain 250 jobs deep.
    // The Developer Edition default maximum queueable stack depth is
    // only 5 (50 in production/sandbox orgs), which causes
    // "Maximum stack depth has been reached" long before the chain
    // finishes. Specifying a larger maximum via AsyncOptions on every
    // enqueue allows the whole chain to run, including synchronously
    // under Test.stopTest(). A delayed enqueue alone (delay 0 or 1)
    // does not reset the stack depth, so the delay is merely the
    // minimum accompanying the extended-depth enqueue.
    private static final Integer MAX_QUEUEABLE_STACK_DEPTH = 1000;
    private static final Integer MIN_QUEUEABLE_DELAY_MINUTES = 1;

    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null
            ? new List<Id>()
            : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(
            new AccountScoringJob(accountIds),
            chainOptions()
        );
    }

    public void execute(QueueableContext context) {
        // The context is intentionally unused so that execute(null) is
        // safe when the job is invoked directly by tests.
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer currentSize = Math.min(
            MAX_ACCOUNTS_PER_EXECUTION,
            accountIds.size()
        );
        List<Id> currentIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();

        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < currentSize) {
                currentIds.add(accountIds[i]);
            } else {
                remainingIds.add(accountIds[i]);
            }
        }

        // The single SOQL query for this execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :currentIds
        ];

        for (Account account : accounts) {
            if (
                account.AnnualRevenue != null &&
                account.AnnualRevenue >= HOT_THRESHOLD
            ) {
                account.Rating = 'Hot';
            } else if (
                account.AnnualRevenue != null &&
                account.AnnualRevenue >= WARM_THRESHOLD
            ) {
                account.Rating = 'Warm';
            } else {
                account.Rating = 'Cold';
            }
        }

        // The single DML statement for this execution.
        update accounts;

        if (!remainingIds.isEmpty()) {
            System.enqueueJob(
                new AccountScoringJob(remainingIds),
                chainOptions()
            );
        }
    }

    private static AsyncOptions chainOptions() {
        AsyncOptions options = new AsyncOptions();
        options.MaximumQueueableStackDepth = MAX_QUEUEABLE_STACK_DEPTH;
        options.MinimumQueueableDelayInMinutes = MIN_QUEUEABLE_DELAY_MINUTES;
        return options;
    }
}
