            OwnerId = fflib_IDGenerator.generate(User.SObjectType),
            StageName = stageName,
            CloseDate = closeDate,
            Amount = amount
        );
    }

    private static void stubSelector(Set<Id> opportunityIds, List<Opportunity> opportunities) {
        mocks.startStubbing();
        mocks.when(selectorMock.selectById(opportunityIds)).thenReturn(opportunities);
        mocks.stopStubbing();
    }

    private static void verifySelectorCalledOnce(Set<Id> opportunityIds) {
        ((IOpportunitiesSelector) mocks.verify(selectorMock, 1)).selectById(opportunityIds);
    }

    private static List<Opportunity> captureRenewals(Integer expectedTimes) {
        fflib_ArgumentCaptor renewalCaptor = fflib_ArgumentCaptor.forClass(Opportunity.class);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, expectedTimes))
            .registerNew((Opportunity) renewalCaptor.capture());

        List<Opportunity> renewals = new List<Opportunity>();
        for (Object captured : renewalCaptor.getAllValues()) {
            renewals.add((Opportunity) captured);
        }
        return renewals;
    }

    private static List<Task> captureTasks(Integer expectedTimes) {
        fflib_ArgumentCaptor taskCaptor = fflib_ArgumentCaptor.forClass(Task.class);
        fflib_ArgumentCaptor fieldCaptor = fflib_ArgumentCaptor.forClass(Schema.SObjectField.class);
        fflib_ArgumentCaptor parentCaptor = fflib_ArgumentCaptor.forClass(Opportunity.class);
        // All three arguments must be matchers/captors: ApexMocks requires
        // that if any argument is a matcher, all of them are. Capturing the
        // SObjectField also lets us pin it to Task.WhatId below.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, expectedTimes))
            .registerNew(
                (Task) taskCaptor.capture(),
                (Schema.SObjectField) fieldCaptor.capture(),
                (Opportunity) parentCaptor.capture()
            );

        List<Task> tasks = new List<Task>();
        for (Object captured : taskCaptor.getAllValues()) {
            tasks.add((Task) captured);
        }
        capturedTaskFields = new List<Schema.SObjectField>();
        for (Object captured : fieldCaptor.getAllValues()) {
            capturedTaskFields.add((Schema.SObjectField) captured);
        }
        capturedTaskParents = new List<Opportunity>();
        for (Object captured : parentCaptor.getAllValues()) {
            capturedTaskParents.add((Opportunity) captured);
        }
        return tasks;
    }

    private static void verifyCommitWork(Integer expectedTimes) {
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, expectedTimes)).commitWork();
    }

    private static void assertRenewal(
