        Assert.areEqual(original.AccountId, renewal.AccountId, 'Renewal AccountId');
        Assert.areEqual('Prospecting', renewal.StageName, 'Renewal StageName');
        Assert.areEqual(expectedCloseDate, renewal.CloseDate, 'Renewal CloseDate must be original CloseDate + 1 year');
        Assert.areEqual(expectedAmount, renewal.Amount, 'Renewal Amount must be original Amount x UPLIFT rounded to 2 decimals');
        Assert.areEqual(
            (original.Amount == null ? null : (original.Amount * RenewalService.UPLIFT).setScale(2)),
            renewal.Amount,
            'Renewal Amount must use RenewalService.UPLIFT'
        );
    }

    private static void assertTask(
        Task reminder,
