        Assert.areEqual(renewal.CloseDate.addDays(-60), reminder.ActivityDate, 'Task ActivityDate relative to renewal CloseDate');
        Assert.isNull(reminder.WhatId, 'Task WhatId must not be set directly to the original Opportunity; the relationship is via the Unit of Work');
        Assert.areEqual(
