        );
        Assert.isTrue(
            renewal === parentUsedForTask,
            'Task must be related via registerNew(task, Task.WhatId, renewal) to the new renewal, not to the original Opportunity'
        );
        Assert.isTrue(
            parentUsedForTask !== original,
            'Task must not be related to the original Opportunity'
        );
    }

