/**
 * Publishes Deal_Stage_Change__e platform events for downstream consumers.
 *
 * DEVIATION FROM THE REQUESTED IMPLEMENTATION:
 * The request was to call EventBus.publish inside the loop, once per
 * Opportunity, collecting each single-event SaveResult. That is not done
 * here; instead the events are built in the loop and published with one
 * bulk EventBus.publish(List<SObject>) call.
 *
 * Reason: each EventBus.publish call counts as a DML statement. Publishing
 * one-by-one for a trigger-sized batch of 200 Opportunities exceeds the
 * 150 DML-statement governor limit (System.LimitException: Too many DML
 * statements: 151) before the batch finishes.
 *
 * No required behaviour is lost: the bulk overload uses a single DML
 * statement regardless of batch size and returns one
 * Database.SaveResult per event, in exactly the same order as the events
 * submitted (and therefore the same order as the input Opportunities).
 * Callers can still identify exactly which event failed by index, e.g.
 * results[i] corresponds to opportunities[i]. The publish-after-commit
 * behaviour of the event is likewise unaffected.
 */
public with sharing class DealEventPublisher {

    /**
     * Publishes one Deal_Stage_Change__e event per supplied Opportunity.
     *
     * @param opportunities Opportunities whose stage changes are to be published.
     * @return One publish Database.SaveResult per input Opportunity, in the
     *         same order as the input list. Returns an empty list and
     *         publishes nothing when the input is null or empty. For
     *         publish-after-commit events, a successful result means the
     *         event was accepted for publication on transaction commit,
     *         not that subscribers have already processed it.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();

        for (Opportunity opp : opportunities) {
            Id oppId = (opp == null) ? null : opp.Id;
            // String conversion of an Apex Id yields its 18-character form.
            String opportunityId18 = (oppId == null) ? null : String.valueOf(oppId);
            String stageName = (opp == null) ? null : opp.StageName;
            Decimal amount = (opp == null) ? null : opp.Amount;

            events.add(
                new Deal_Stage_Change__e(
                    Opportunity_Id__c = opportunityId18,
                    Stage__c = stageName,
                    Amount__c = amount
                )
            );
        }

        // Single bulk publish (one DML statement). Results are 1:1 with,
        // and in the same order as, the submitted events / input list.
        return EventBus.publish(events);
    }
}
