public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest request : requests) {
            if (request == null) {
                throw new SoftCreditException('Soft credit request cannot be null.');
            }
            if (request.opportunityId != null) {
                opportunityIds.add(request.opportunityId);
            }
            if (request.contactId != null) {
                contactIds.add(request.contactId);
            }
        }

        // SOQL 1: Opportunities needed for validation.
        Map<Id, Opportunity> opportunityById = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]);

        // Validate the entire call before any DML.
        for (SoftCreditRequest request : requests) {
            if (request.opportunityId == null || request.contactId == null) {
                throw new SoftCreditException('Opportunity and contact are required for a soft credit.');
            }

            Opportunity opportunity = opportunityById.get(request.opportunityId);
            if (opportunity == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + request.opportunityId
                );
            }
            if (request.amount == null || request.amount <= 0) {
                throw new SoftCreditException(
                    'Partial soft credit amount must be positive.'
                );
            }
            if (opportunity.Amount == null || request.amount > opportunity.Amount) {
                throw new SoftCreditException(
                    'Partial soft credit amount cannot exceed the opportunity amount.'
                );
            }
            if (request.contactId == opportunity.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'The opportunity primary contact cannot receive a partial soft credit.'
                );
            }
        }

        // SOQL 2: Existing contact roles for the requested pairs.
        List<OpportunityContactRole> existingContactRoles = [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
              AND ContactId IN :contactIds
        ];

        Map<String, OpportunityContactRole> contactRoleByKey =
            new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> duplicateContactRoles =
            new List<OpportunityContactRole>();

        for (OpportunityContactRole contactRole : existingContactRoles) {
            String key = pairKey(contactRole.OpportunityId, contactRole.ContactId);
            if (contactRoleByKey.containsKey(key)) {
                duplicateContactRoles.add(contactRole);
            } else {
                contactRoleByKey.put(key, contactRole);
            }
        }

        List<OpportunityContactRole> contactRolesToUpsert =
            new List<OpportunityContactRole>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);
            OpportunityContactRole contactRole = contactRoleByKey.get(key);

            if (contactRole == null) {
                contactRole = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role
                );
                contactRoleByKey.put(key, contactRole);
                contactRolesToUpsert.add(contactRole);
            } else if (contactRole.Role != request.role) {
                contactRole.Role = request.role;
                contactRolesToUpsert.add(contactRole);
            }
        }

        // Remove any duplicate roles first so each pair ends with exactly one.
        if (!duplicateContactRoles.isEmpty()) {
            delete duplicateContactRoles;
        }
        if (!contactRolesToUpsert.isEmpty()) {
            upsert contactRolesToUpsert;
        }

        // NPSP's Contact_Name__c may be a lookup, text, or calculated field
        // depending on the org. Populate it only when it is writable.
        // Note: Schema...fields.<field> returns DescribeFieldResult, not SObjectField.
        Boolean populateContactName = false;
        Boolean contactNameIsReference = false;
        Schema.DescribeFieldResult contactNameDescribe =
            Schema.SObjectType.npsp__Partial_Soft_Credit__c
                .fields.npsp__Contact_Name__c;
        if (contactNameDescribe != null) {
            populateContactName =
                !contactNameDescribe.isCalculated() &&
                !contactNameDescribe.isAutoNumber() &&
                (contactNameDescribe.isCreateable() ||
                 contactNameDescribe.isUpdateable());
            contactNameIsReference =
                contactNameDescribe.getType() == Schema.DisplayType.REFERENCE;
        }

        // SOQL 3: Query partial soft credits after the contact-role DML.
        // This finds both pre-existing records and any record NPSP automation
        // may have created in response to the contact-role change.
        List<npsp__Partial_Soft_Credit__c> existingSoftCredits = [
            SELECT Id,
                   npsp__Opportunity__c,
                   npsp__Contact__c,
                   npsp__Amount__c,
                   npsp__Role_Name__c,
                   npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
              AND npsp__Contact__c IN :contactIds
        ];

        Map<String, npsp__Partial_Soft_Credit__c> softCreditByKey =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> duplicateSoftCredits =
            new List<npsp__Partial_Soft_Credit__c>();

        for (npsp__Partial_Soft_Credit__c softCredit : existingSoftCredits) {
            String key = pairKey(
                softCredit.npsp__Opportunity__c,
                softCredit.npsp__Contact__c
            );
            if (softCreditByKey.containsKey(key)) {
                duplicateSoftCredits.add(softCredit);
            } else {
                softCreditByKey.put(key, softCredit);
            }
        }

        List<npsp__Partial_Soft_Credit__c> softCreditsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);
            OpportunityContactRole contactRole = contactRoleByKey.get(key);
            npsp__Partial_Soft_Credit__c softCredit = softCreditByKey.get(key);
            Boolean isNew = (softCredit == null);

            if (isNew) {
                softCredit = new npsp__Partial_Soft_Credit__c();
                // npsp__Opportunity__c is a master-detail field: it is
                // createable but not updateable, so it (and the other
                // relationship fields) must only be assigned on insert.
                // Assigning it on a queried, existing record throws
                // "Field is not writeable" even when the value is unchanged.
                softCredit.npsp__Opportunity__c = request.opportunityId;
                softCredit.npsp__Contact__c = request.contactId;
                softCreditByKey.put(key, softCredit);
            }

            // Only mutable fields are assigned for existing records.
            softCredit.npsp__Amount__c = request.amount;
            softCredit.npsp__Role_Name__c = request.role;
            softCredit.npsp__Contact_Role_ID__c = String.valueOf(contactRole.Id);

            if (populateContactName && isNew) {
                if (contactNameIsReference) {
                    softCredit.put(
                        'npsp__Contact_Name__c',
                        request.contactId
                    );
                } else {
                    softCredit.put(
                        'npsp__Contact_Name__c',
                        String.valueOf(request.contactId)
                    );
                }
            }

            softCreditsToUpsert.add(softCredit);
        }

        if (!duplicateSoftCredits.isEmpty()) {
            delete duplicateSoftCredits;
        }
        if (!softCreditsToUpsert.isEmpty()) {
            upsert softCreditsToUpsert;
        }
    }

    private static String pairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + '|' + String.valueOf(contactId);
    }
}
